#define _XOPEN_SOURCE 700

#include <errno.h>
#include <poll.h>
#include <signal.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>

#include "platform.h"
#include "term.h"

/*
 * The alternate screen with a hidden cursor and the mouse, and back. The
 * mouse is xterm tracking: 1000 clicks, 1002 moves with a button held,
 * 1006 SGR coordinates (no limit of 223 columns). OSC 11 with "?" asks
 * for the background colour; the answer comes as input (KEY_BACKGROUND),
 * also after a stop, when the system may have changed its appearance.
 */
#define TERM_ENTER "\033[?1049h\033[?25l\033[?1000h\033[?1002h\033[?1006h" \
	"\033]11;?\033\\"
#define TERM_LEAVE "\033[?1006l\033[?1002l\033[?1000l\033[0m\033[?25h" \
	"\033[?1049l"

static struct termios saved, raw;
static volatile sig_atomic_t raw_on, redraw;
static int opened, registered;

/* Only write and tcsetattr: both are safe in a signal handler. */
static void write_all(const char *s, size_t len)
{
	ssize_t n;

	while (len > 0) {
		n = write(STDOUT_FILENO, s, len);
		if (n < 0 && errno == EINTR)
			continue;
		if (n <= 0)
			return;
		s += n;
		len -= (size_t)n;
	}
}

static void raw_enter(void)
{
	tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw);
	write_all(TERM_ENTER, sizeof TERM_ENTER - 1);
	raw_on = 1;
}

static void raw_leave(void)
{
	if (!raw_on)
		return;
	write_all(TERM_LEAVE, sizeof TERM_LEAVE - 1);
	tcsetattr(STDIN_FILENO, TCSAFLUSH, &saved);
	raw_on = 0;
}

static void set_handler(int sig, void (*handler)(int))
{
	struct sigaction sa;

	memset(&sa, 0, sizeof sa);
	sa.sa_handler = handler;
	sigemptyset(&sa.sa_mask);
	sigaction(sig, &sa, NULL);
}

/* SIGINT, SIGTERM: the terminal comes back, then the signal does its work. */
static void on_fatal(int sig)
{
	raw_leave();
	set_handler(sig, SIG_DFL);
	raise(sig);
}

/*
 * SIGTSTP (Ctrl-Z): the shell gets its terminal back before the stop.
 * The raised signal waits until it is unblocked, then stops the process
 * here; SIGCONT restores the screen when it goes on. A process group
 * without job control (orphaned) does not stop at all, so then the
 * screen comes back at once.
 */
static void on_stop(int sig)
{
	sigset_t set;

	raw_leave();
	set_handler(sig, SIG_DFL);
	raise(sig);
	sigemptyset(&set);
	sigaddset(&set, sig);
	sigprocmask(SIG_UNBLOCK, &set, NULL);
	set_handler(sig, on_stop);
	if (!raw_on) {
		raw_enter();
		redraw = 1;
	}
}

static void on_continue(int sig)
{
	(void)sig;
	raw_enter();
	redraw = 1;
}

static void on_resize(int sig)
{
	(void)sig;
	redraw = 1;
}

/*
 * Raw input without echo, the alternate screen, the signal handlers.
 * ISIG stays on, so Ctrl-C and Ctrl-Z work as everywhere else.
 */
int term_open(void)
{
	if (!isatty(STDIN_FILENO) || !isatty(STDOUT_FILENO)) {
		errno = ENOTTY;
		return -1;
	}
	if (tcgetattr(STDIN_FILENO, &saved) != 0)
		return -1;
	raw = saved;
	raw.c_iflag &= ~(tcflag_t)(BRKINT | ICRNL | INPCK | ISTRIP | IXON);
	raw.c_oflag &= ~(tcflag_t)OPOST;
	raw.c_cflag |= CS8;
	raw.c_lflag &= ~(tcflag_t)(ECHO | ICANON | IEXTEN);
	raw.c_cc[VMIN] = 1;
	raw.c_cc[VTIME] = 0;
	/* exit() from anywhere (out of memory) restores the terminal too. */
	if (!registered && atexit(term_close) == 0)
		registered = 1;
	set_handler(SIGINT, on_fatal);
	set_handler(SIGTERM, on_fatal);
	set_handler(SIGHUP, on_fatal);
	set_handler(SIGTSTP, on_stop);
	set_handler(SIGCONT, on_continue);
	set_handler(platform_resize_signal(), on_resize);
	raw_enter();
	opened = 1;
	return 0;
}

void term_close(void)
{
	if (!opened)
		return;
	raw_leave();
	set_handler(SIGINT, SIG_DFL);
	set_handler(SIGTERM, SIG_DFL);
	set_handler(SIGHUP, SIG_DFL);
	set_handler(SIGTSTP, SIG_DFL);
	set_handler(SIGCONT, SIG_DFL);
	set_handler(platform_resize_signal(), SIG_DFL);
	opened = 0;
}

int term_size(size_t *cols, size_t *rows)
{
	return platform_term_size(STDOUT_FILENO, cols, rows);
}

int term_write(const char *s, size_t len)
{
	write_all(s, len);
	return 0;
}

/* Waits for input at most timeout_ms (-1: no limit). */
enum term_event term_wait(int timeout_ms)
{
	struct pollfd p;
	int r;

	if (redraw) {
		redraw = 0;
		return TERM_RESIZE;
	}
	p.fd = STDIN_FILENO;
	p.events = POLLIN;
	p.revents = 0;
	r = poll(&p, 1, timeout_ms);
	if (redraw) {
		redraw = 0;
		return TERM_RESIZE;
	}
	if (r < 0)
		return errno == EINTR ? TERM_TIMEOUT : TERM_ERROR;
	if (r == 0)
		return TERM_TIMEOUT;
	if (p.revents & (POLLERR | POLLHUP | POLLNVAL))
		return TERM_ERROR;
	return TERM_INPUT;
}

/* The bytes waiting on the terminal; 0 at the end of input or on error. */
size_t term_read(unsigned char *buf, size_t size)
{
	ssize_t n;

	do
		n = read(STDIN_FILENO, buf, size);
	while (n < 0 && errno == EINTR);
	return n > 0 ? (size_t)n : 0;
}

static enum key_code tilde_key(const unsigned char *p, size_t n)
{
	size_t v = 0, i;

	/* "5;2~" is PgUp with Shift: the number before ";" names the key. */
	for (i = 0; i < n && p[i] >= '0' && p[i] <= '9'; i++)
		v = v * 10 + (size_t)(p[i] - '0');
	switch (v) {
	case 1:
	case 7:
		return KEY_HOME;
	case 3:
		return KEY_DELETE;
	case 4:
	case 8:
		return KEY_END;
	case 5:
		return KEY_PAGE_UP;
	case 6:
		return KEY_PAGE_DOWN;
	}
	return KEY_NONE;
}

static enum key_code letter_key(int c)
{
	switch (c) {
	case 'A':
		return KEY_UP;
	case 'B':
		return KEY_DOWN;
	case 'C':
		return KEY_RIGHT;
	case 'D':
		return KEY_LEFT;
	case 'H':
		return KEY_HOME;
	case 'F':
		return KEY_END;
	}
	return KEY_NONE;
}

/*
 * An SGR mouse report, "<b;x;yM" (or "m" on release) between "ESC [" and
 * the end. Bits of b: 0-1 the button, 4 Shift, 8 Alt, 16 Ctrl, 32 a move,
 * 64 the wheel. Anything else, such as a move with no button, is nothing.
 */
static void decode_mouse(const unsigned char *p, size_t n, int release,
    struct key *k)
{
	size_t v[3] = { 0, 0, 0 }, f = 0, i;

	for (i = 1; i < n; i++) {
		if (p[i] == ';') {
			if (++f == 3)
				return;
		} else if (p[i] >= '0' && p[i] <= '9' && v[f] < 100000) {
			v[f] = v[f] * 10 + (size_t)(p[i] - '0');
		} else {
			return;
		}
	}
	if (f != 2 || v[1] == 0 || v[2] == 0)
		return;
	k->mods = (v[0] & 4 ? MOD_SHIFT : 0) | (v[0] & 8 ? MOD_ALT : 0) |
	    (v[0] & 16 ? MOD_CTRL : 0);
	k->button = (int)(v[0] & 3);
	k->x = v[1] - 1;
	k->y = v[2] - 1;
	if (v[0] & 64) {
		if (k->button > 1)
			return;
		k->mouse = k->button == 0 ? MOUSE_WHEEL_UP : MOUSE_WHEEL_DOWN;
		k->button = 0;
	} else if (k->button == 3) {
		return;
	} else if (release) {
		k->mouse = MOUSE_RELEASE;
	} else {
		k->mouse = v[0] & 32 ? MOUSE_DRAG : MOUSE_PRESS;
	}
	k->code = KEY_MOUSE;
}

/* One colour of "rgb:R/G/B": 1 to 4 hex digits, as a share of 0-1000. */
static const unsigned char *hex_part(const unsigned char *p,
    const unsigned char *end, unsigned *share)
{
	unsigned long v = 0, top = 0;
	int c, n;

	for (n = 0; n < 4 && p < end; n++, p++) {
		c = *p;
		if (c >= '0' && c <= '9')
			c -= '0';
		else if (c >= 'a' && c <= 'f')
			c -= 'a' - 10;
		else if (c >= 'A' && c <= 'F')
			c -= 'A' - 10;
		else
			break;
		v = v * 16 + (unsigned long)c;
		top = top * 16 + 15;
	}
	if (n == 0)
		return NULL;
	*share = (unsigned)(v * 1000 / top);
	return p;
}

/*
 * The answer to OSC 11: "11;rgb:R/G/B" (or "rgba:" with alpha after).
 * Dark is a luminance (Rec. 709 weights) below one half.
 */
static void decode_background(const unsigned char *p, size_t n, struct key *k)
{
	const unsigned char *end = p + n;
	unsigned rgb[3];
	size_t i;

	if (n > 7 && memcmp(p, "11;rgb:", 7) == 0)
		p += 7;
	else if (n > 8 && memcmp(p, "11;rgba:", 8) == 0)
		p += 8;
	else
		return;
	for (i = 0; i < 3; i++) {
		if (i > 0) {
			if (p == end || *p != '/')
				return;
			p++;
		}
		p = hex_part(p, end, &rgb[i]);
		if (p == NULL)
			return;
	}
	if (p != end && *p != '/')
		return;
	k->code = KEY_BACKGROUND;
	k->dark = 2126 * rgb[0] + 7152 * rgb[1] + 722 * rgb[2] < 5000000;
}

/*
 * An OSC string, "ESC ]" up to BEL or "ESC \": consumed whole, so the
 * terminal's answers never turn into keys.
 */
static size_t decode_osc(const unsigned char *b, size_t len, int more,
    struct key *k)
{
	size_t i;

	for (i = 2; i < len; i++) {
		if (b[i] == 007) {
			decode_background(b + 2, i - 2, k);
			return i + 1;
		}
		if (b[i] == 033) {
			if (i + 1 == len)
				break;
			if (b[i + 1] != '\\')
				return i;
			decode_background(b + 2, i - 2, k);
			return i + 2;
		}
	}
	return more ? 0 : len;
}

/*
 * ESC alone is the Esc key only when nothing follows (more is 0). A CSI
 * sequence is consumed whole even when unknown, so mouse reports and the
 * like never turn into letters; so is an OSC string. ESC before anything
 * else is Esc, and the next byte is a key of its own.
 */
static size_t decode_escape(const unsigned char *b, size_t len, int more,
    struct key *k)
{
	size_t i;

	if (len == 1) {
		if (more)
			return 0;
		k->code = KEY_ESC;
		return 1;
	}
	if (b[1] == '[') {
		for (i = 2; i < len && b[i] >= 0x30 && b[i] <= 0x3f; i++)
			;
		while (i < len && b[i] >= 0x20 && b[i] <= 0x2f)
			i++;
		if (i == len)
			return more ? 0 : len;
		if (b[i] < 0x40 || b[i] > 0x7e)
			return i;
		if (b[2] == '<' && (b[i] == 'M' || b[i] == 'm'))
			decode_mouse(b + 2, i - 2, b[i] == 'm', k);
		else if (b[i] == '~')
			k->code = tilde_key(b + 2, i - 2);
		else if (b[i] == 'Z')
			k->code = KEY_BACKTAB;
		else
			k->code = letter_key(b[i]);
		return i + 1;
	}
	if (b[1] == ']')
		return decode_osc(b, len, more, k);
	if (b[1] == 'O') {
		if (len < 3)
			return more ? 0 : len;
		k->code = letter_key(b[2]);
		return 3;
	}
	k->code = KEY_ESC;
	return 1;
}

/*
 * The first key in buf: the bytes it takes, or 0 when it is incomplete
 * and more may still come. Bytes that mean nothing are consumed as
 * KEY_NONE.
 */
size_t key_decode(const unsigned char *b, size_t len, int more,
    struct key *k)
{
	size_t n, i;

	memset(k, 0, sizeof *k);
	k->code = KEY_NONE;
	if (len == 0)
		return 0;
	if (b[0] == 033)
		return decode_escape(b, len, more, k);
	if (b[0] == '\r' || b[0] == '\n') {
		k->code = KEY_ENTER;
		return 1;
	}
	if (b[0] == '\t') {
		k->code = KEY_TAB;
		return 1;
	}
	if (b[0] == 0x7f || b[0] == '\b') {
		k->code = KEY_BACKSPACE;
		return 1;
	}
	if (b[0] >= 1 && b[0] <= 26) {
		k->code = KEY_CTRL;
		k->text[0] = (char)('a' + b[0] - 1);
		k->text[1] = '\0';
		return 1;
	}
	if (b[0] < 0x20)
		return 1;
	if (b[0] < 0x80)
		n = 1;
	else if (b[0] >= 0xc2 && b[0] <= 0xdf)
		n = 2;
	else if (b[0] >= 0xe0 && b[0] <= 0xef)
		n = 3;
	else if (b[0] >= 0xf0 && b[0] <= 0xf4)
		n = 4;
	else
		return 1;
	if (len < n)
		return more ? 0 : 1;
	for (i = 1; i < n; i++)
		if ((b[i] & 0xc0) != 0x80)
			return 1;
	k->code = KEY_CHAR;
	memcpy(k->text, b, n);
	k->text[n] = '\0';
	return n;
}
